// RedLetterTruth.swift
// The markup-carrying sources' Jesus-speech truth, extracted
// from the published NASB1995 and KJV modules and bundled with
// the app (REQ-RL-5): per verse, the speech spans in the source
// verse's own plain text, that text's length, and the quotation
// depth carried into the verse from earlier verses of the book.
// Bundling the extraction means derivation (REQ-RL-5) needs
// neither source module installed on the device. The tables
// hold only published-module data.

import Foundation

public enum RedLetterTruth {
    /// Source ids in priority order: the first source's
    /// derivation wins wherever it paints.
    public static let sourceIDs = ["nasb1995", "kjv"]

    /// One source's truth for one chapter of a book (canonical
    /// English book name), keyed by verse number; empty when the
    /// source tags nothing there.
    public static func truth(sourceID: String, book: String, chapter: Int)
        -> [Int: RedLetterDerivation.TruthVerse]
    {
        guard let bookTable = table[sourceID.lowercased()]?[book] else { return [:] }
        let prefix = "\(chapter)."
        var out: [Int: RedLetterDerivation.TruthVerse] = [:]
        for (ref, entry) in bookTable where ref.hasPrefix(prefix) {
            guard let verse = Int(ref.dropFirst(prefix.count)) else { continue }
            out[verse] = entry
        }
        return out
    }

    private static let table: [String: [String: [String: RedLetterDerivation.TruthVerse]]] = {
        guard let data = json.data(using: .utf8),
              let object = try? JSONSerialization.jsonObject(with: data),
              let raw = object as? [String: [String: [String: [String: Any]]]]
        else { return [:] }
        var out: [String: [String: [String: RedLetterDerivation.TruthVerse]]] = [:]
        for (sourceID, books) in raw {
            var bookOut: [String: [String: RedLetterDerivation.TruthVerse]] = [:]
            for (book, verses) in books {
                var verseOut: [String: RedLetterDerivation.TruthVerse] = [:]
                for (ref, entry) in verses {
                    let spans = (entry["s"] as? [[Int]] ?? []).compactMap {
                        $0.count == 2 ? (start: $0[0], end: $0[1]) : nil
                    }
                    verseOut[ref] = RedLetterDerivation.TruthVerse(
                        spans: spans,
                        textLength: entry["l"] as? Int ?? 0,
                        depthIn: entry["d"] as? Int ?? 0)
                }
                bookOut[book] = verseOut
            }
            out[sourceID] = bookOut
        }
        return out
    }()

